import { describe, expect, test } from "vitest";
import {
  describeProtectResult,
  protectRecords,
  type ProtectableRecord,
} from "../../src/core/protectExternalEdits";

/**
 * 拡張機能の外で直された設定資料を守る（設計書5.5）。
 *
 * **決まったこと（2026-08-19、作者の判断）**
 *
 * - 編集部の書いた記述は、作者の記述と同じように守る
 * - AIの抽出が編集部の記述と食い違ったら、編集部を優先する
 *
 * **守る仕組みはもともとある。** マージは `autoGenerated: false` の
 * レコードをAIで書き換えない。この判定は**誰が書いたかを見ていない**ので、
 * 編集部の記述も作者の記述と同じように守られる。
 *
 * **抜けていたのは、印の付き方である。** 編集部はGitHub経由で直すので
 * 拡張機能の画面を通らず、AI生成のままのレコードには印が付かない。
 */
function record(name: string, autoGenerated: boolean): ProtectableRecord {
  return { name, autoGenerated };
}

describe("印を付ける", () => {
  test("AI生成のままのものに印を付ける", () => {
    const records = [record("太志", true), record("ナイン", true)];
    const result = protectRecords(records);

    expect(result.protectedRecords).toHaveLength(2);
    expect(records.every((entry) => entry.autoGenerated === false)).toBe(true);
  });

  test("もともと印が付いているものには触らない", () => {
    // **触っていないことが分かるように分けて返す。**
    // 「10件のうち3件を守りました」と言えると、何が起きたか伝わる
    const records = [record("太志", false), record("ナイン", true)];
    const result = protectRecords(records);

    expect(result.protectedRecords.map((entry) => entry.name)).toEqual([
      "ナイン",
    ]);
    expect(result.alreadyProtected.map((entry) => entry.name)).toEqual(["太志"]);
  });

  test("1件も無ければ空", () => {
    const result = protectRecords([]);

    expect(result.protectedRecords).toEqual([]);
    expect(result.alreadyProtected).toEqual([]);
  });
});

describe("作者への報告", () => {
  test("何件を守ったかと、名前を出す", () => {
    const message = describeProtectResult(
      protectRecords([record("太志", true), record("ナイン", true)])
    );

    expect(message).toContain("2件");
    expect(message).toContain("太志");
    expect(message).toContain("ナイン");
  });

  test("多いときは省いて件数で伝える", () => {
    const many = Array.from({ length: 8 }, (_, index) =>
      record(`人物${index}`, true)
    );
    const message = describeProtectResult(protectRecords(many));

    expect(message).toContain("8件");
    expect(message).toContain("ほか3件");
  });

  test("もともと守られていた件数も伝える", () => {
    const message = describeProtectResult(
      protectRecords([record("太志", true), record("ナイン", false)])
    );

    expect(message).toContain("1件はもともとその設定でした");
  });

  test("全部もともと守られていたなら、そう言う", () => {
    const message = describeProtectResult(
      protectRecords([record("太志", false)])
    );

    expect(message).toContain("もともとAIで上書きされない設定でした");
  });

  test("対象が無ければ、そう言う", () => {
    expect(describeProtectResult(protectRecords([]))).toContain(
      "守る対象がありませんでした"
    );
  });
});
